pub struct AgentLoop<B: Browser> {
    browser: B,
    clients: LlmClients,
    router: Router,
    validator: Validator,
    policy: AgentPolicy,
    memory: Memory,
    task: String,
}

impl<B: Browser> AgentLoop<B> {
    pub fn new(browser: B, clients: LlmClients, task: impl Into<String>) -> Self {
        let policy = AgentPolicy::default();
        let memory = Memory::new(policy.memory.clone());
        Self {
            browser,
            clients,
            router: Router::default(),
            validator: Validator::default(),
            policy,
            memory,
            task: task.into(),
        }
    }

    pub fn with_plan(mut self, plan: impl Into<String>) -> Self {
        self.memory.set_plan(Some(plan.into()));
        self
    }

    pub fn with_policy(mut self, policy: AgentPolicy) -> Self {
        let plan = self.memory.plan().map(|value| value.to_string());
        self.policy = policy;
        self.memory = Memory::new(self.policy.memory.clone());
        self.memory.set_plan(plan);
        self
    }

    pub fn with_router(mut self, router: Router) -> Self {
        self.router = router;
        self
    }

    pub fn with_validator(mut self, validator: Validator) -> Self {
        self.validator = validator;
        self
    }

    pub fn memory(&self) -> &Memory {
        &self.memory
    }

    pub async fn shutdown(&self) -> Result<(), BrowserError> {
        self.browser.shutdown().await
    }

    pub async fn run(&mut self) -> Result<RunResult, AgentError> {
        enum StepControl {
            Continue,
            Done(Action),
        }

        let snapshot_start = Instant::now();
        let mut observation = match self.browser.snapshot().await {
            Ok(observation) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                observation
            }
            Err(err) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                tracing::error!(
                    event = "snapshot_error",
                    error_code = err.code,
                    error_message = %err.message
                );
                return Err(AgentError::Browser(err));
            }
        };
        self.memory.record_observation(observation.clone());

        for step_index in 0..self.policy.max_steps {
            let tier = self.router.tier();
            telemetry::inc_step();

            let step_span = tracing::info_span!(
                "step",
                step_index = step_index + 1,
                tier = ?tier,
                url = %observation.url,
                state_hash = ?observation.state_hash
            );

            let step_result = async {
                let step_start = Instant::now();
                let client = self.clients.client(tier);

                let action = match client
                    .propose_action(
                        &self.task,
                        self.memory.plan(),
                        &observation,
                        self.memory.history(),
                    )
                    .await
                {
                    Ok(action) => action,
                    Err(err) => {
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "llm_error",
                            error_code = err.code,
                            error_message_len = err.message.chars().count(),
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Llm(err));
                    }
                };

                telemetry::inc_action(&action);
                tracing::info!(
                    event = "action_proposed",
                    action_type = telemetry::action_type(&action),
                    action = ?telemetry::ActionSummary::from(&action)
                );

                if let Err(errors) = self.validator.validate(&action, &observation) {
                    let error_count = errors.len();
                    telemetry::inc_validation_failure();
                    let mut result = validation_result(errors);
                    result.new_state_hash = Some(observation.state_hash.clone());
                    self.memory.record_step(action, result);
                    let tier_after = self.router.record(StepOutcome::Failure);
                    telemetry::set_no_progress_streak(self.router.counters().no_progress);
                    let duration = step_start.elapsed();
                    telemetry::record_step_duration(duration);
                    tracing::warn!(
                        event = "validation_failed",
                        error_count = error_count,
                        tier = ?tier_after,
                        step_duration_ms = duration.as_millis() as u64

                model: config.model_fast.clone(),
                timeout,
                temperature: config.temperature,
                max_tokens: config.max_tokens,
            })?;
            let mid = OpenAiClient::new(OpenAiConfig {
                api_key: api_key.to_string(),
                base_url: config.base_url.clone(),
                model: config.model_mid.clone(),
                timeout,
                temperature: config.temperature,
                max_tokens: config.max_tokens,
            })?;
            let strong = OpenAiClient::new(OpenAiConfig {
                api_key: api_key.to_string(),
                base_url: config.base_url.clone(),
                model: config.model_strong.clone(),
                timeout,
                temperature: config.temperature,
                max_tokens: config.max_tokens,
            })?;
            Ok(LlmClients::new(
                Box::new(fast),
                Box::new(mid),
                Box::new(strong),
            ))
        }
    }
}

async fn execute_agent(
    task: &str,
    plan: Option<&str>,
    config: &mbus::config::AppConfig,
) -> Result<RunResult, Box<dyn Error>> {
    let browser = CdpBrowser::launch(config.browser.clone()).await?;
    let clients = build_clients(&config.llm)?;

    let mut agent = AgentLoop::new(browser, clients, task.to_string())
        .with_policy(config.agent.clone())
        .with_router(Router::new(config.router.clone()))
        .with_validator(Validator::new(config.validator.clone()));
    if let Some(plan) = plan {
        agent = agent.with_plan(plan.to_string());
    }

    let run_result = agent.run().await;
    let shutdown_result = agent.shutdown().await;
    if let Err(err) = shutdown_result {
        eprintln!("shutdown error: {err}");
    }

    Ok(run_result?)
}

fn emit_run_logs(result: &mbus::agent::r#loop::RunResult) -> Result<(), Box<dyn Error>> {
    for (index, step) in result.steps.iter().enumerate() {
        emit_json(&StepLog {
            r#type: "step",
            index: index + 1,
            action: step.action.clone(),
            result: step.result.clone(),
        })?;
    }

    let status = match result.status {
        RunStatus::Done => "done",
        RunStatus::MaxSteps => "max_steps",
    };

    emit_json(&SummaryLog {
        r#type: "summary",
        status,
        final_action: result.final_action.clone(),
        steps: result.steps.len(),
        final_url: result.final_observation.url.clone(),
        final_title: result.final_observation.title.clone(),
    })?;

    Ok(())
}

fn write_extract_output(
    task: &str,
    config: &mbus::config::AppConfig,
    result: &mbus::agent::r#loop::RunResult,
) -> Result<(), Box<dyn Error>> {
    let Some(path) = config.output.extract_output.as_ref() else {
        return Ok(());
    };
    let task_id = mbus::output::task_id_for(task);
    let timestamp = mbus::output::current_timestamp()?;
    if let Some(output) = mbus::output::build_extract_output(task_id, timestamp, &result.steps) {
        mbus::output::write_extract_output(path, &output)?;
    }
    Ok(())
}

fn emit_json<T: Serialize>(value: &T) -> Result<(), Box<dyn Error>> {
    let text = serde_json::to_string(value)?;
    println!("{text}");
    Ok(())
}

